{
  "stageDiagnosis": "客户处于初步跟进阶段，暂未量房或报价（报价状态为空），因个人时间紧张而延迟沟通，关注价格与施工质量，并在比较1家竞品。",
  "priorityReason": "今日为计划跟进日（customer.nextFollowAt=2026-09-26），且距上次沟通已4天，客户可能已度过忙碌期，及时唤醒可避免其转向竞品。",
  "goal": "通过轻量、有价值的信息重新建立联系，确认客户当前装修意向与时间安排。",
  "questions": [
    "最近是否还在考虑为新家做装修规划？",
    "您对价格和施工质量方面有什么特别想了解的吗？",
    "如果方便，我们可以约个时间简单沟通一下量房和方案，您看本周或下周什么时候有空？"
  ],
  "talkTrack": [
    "您好，上次您提到最近比较忙，所以没有打扰。今天想分享一个想法：您108平的毛坯房和16万预算，我们可以帮您做一个资金规划参考，不涉及具体报价，只是思路，您有兴趣看看吗？",
    "如果担心施工质量，我们可以在后续沟通中提供我们的施工标准和验收流程说明，您看可以吗？"
  ],
  "objectionHandling": [
    {
      "ifCustomerSays": "还是忙，没时间看",
      "reply": "完全理解，您不用现在看，我发一两个简单易懂的图文，您有空时扫一眼就行，不占用太多时间。"
    },
    {
      "ifCustomerSays": "预算16万怕不够，质量也担心",
      "reply": "装修预算确实需要精细规划，我们可以根据您的需求（自住、首套）给出实际建议，不会超预算。质量方面我们有明确的施工验收标准，后续会写进合同。"
    },
    {
      "ifCustomerSays": "我还在比较另一家",
      "reply": "比较是应该的，我们希望通过透明的方案和实在的沟通让您更放心。您可以把别家的报价拿来看看，我们帮您分析一下有什么不同。"
    }
  ],
  "recommendedMaterials": [
    "待确认：是否有针对108平米毛坯的预算分配指南或装修流程说明可发送",
    "暂不发送正式报价，因报价状态为空"
  ],
  "forbidden": [
    "不得承诺具体价格优惠或折扣",
    "不得承诺具体工期",
    "不得编造已签约客户好评或案例",
    "不得保证施工质量无任何问题（应说明有合同保障）"
  ],
  "nextFollowAt": "若本次无回应，建议2026-09-30再次发送一条轻提醒；若有回应并推进，则按预约时间跟进。",
  "next

{
  "stageDiagnosis": "客户已量房，处于方案报价阶段，设计稿为草稿状态，报价未出。客户主动追问设计费，说明其对价格敏感且担心未签约产生费用，真实卡点是设计费规则不明确导致决策顾虑。",
  "priorityReason": "客户主动询问设计费，表明其正在评估合作成本，若不及时澄清可能因误解而流失；且已到计划跟进日期，需立即回应以推进方案确认。",
  "goal": "明确设计费规则，消除客户对未签约费用的顾虑，推动客户确认设计方案并进入报价环节。",
  "questions": [
    "您对目前的设计草案有哪些具体想法或需要调整的地方？",
    "除了设计费，您对整体预算还有其他特别关注的部分吗？",
    "您希望我们下一步优先提供详细报价还是先完善设计方案？"
  ],
  "talkTrack": [
    "王先生您好，关于设计费的问题，我们公司目前有明确制度：量房后提供设计方案，若最终未签约，设计费是不收取的；只有签约后才会根据合同约定计算设计费，具体金额会在正式报价中列明。",
    "您放心，我们先把方案调整到您满意，再给您出详细报价，所有费用都会提前说清楚，不会让您承担任何隐性成本。"
  ],
  "objectionHandling": [
    {
      "ifCustomerSays": "如果设计费很高，我就不考虑了。",
      "reply": "理解您的担心。我们的设计费标准是公开透明的，而且如果最终不签约，设计阶段是不收费的。您可以先看方案和报价，觉得合适再决定。"
    },
    {
      "ifCustomerSays": "别家设计是免费的，你们为什么要收？",
      "reply": "每家公司的服务模式不同。我们提供的是个性化设计服务，设计费对应的是专业设计师的投入。不过，如果您最终选择我们施工，设计费可能会有优惠，具体可以在报价中体现。"
    }
  ],
  "recommendedMaterials": [
    "正式的设计费收费标准说明",
    "已授权的设计费优惠案例（如有）"
  ],
  "forbidden": [
    "不得承诺设计费具体金额或折扣，除非有正式制度依据",
    "不得暗示设计费可完全免除，除非公司政策明确允许"
  ],
  "nextFollowAt": "2026-09-27",
  "nextAction": "回复客户设计费规则后，记录客户反馈，并预约一次方案沟通或报价发送时间。",
  "evidenceRefs": [
    "customer.concerns",
    "customer.designStatus",
    "customer.quoteStatus",
    "timeline[0].content"
  ]
}

{
  "stageDiagnosis": "客户原已约定量房，但于9月25日提出推迟，原因是父母作为出资方要求再看看。当前卡点是父母决策未打通，客户自身可能不确定，但主要障碍是父母意见。",
  "priorityReason": "今天是原定跟进日，且客户刚在昨天提出推迟，必须及时响应以理解真实顾虑并尽力挽救量房机会，否则可能导致客户流失或转向竞品。",
  "goal": "争取与客户沟通，了解父母具体顾虑，并重新确认量房时间（即使不是原时间，也说服先进行免费量房）。",
  "questions": [
    "父母主要顾虑是预算、工期，还是对装修公司不放心？能否具体说说？",
    "父母是否愿意一起到店沟通，或者需要我们提供哪些资料给他们参考？",
    "量房本身不收费也不产生义务，是否可以先量房，等方案和报价出来后再给父母看？这样能节省时间。"
  ],
  "talkTrack": [
    "理解父母想多比较的心情，毕竟装修是大事。不过量房是免费服务，而且量完房我们才能给出准确方案和报价，这样父母也能更直观地比较。您看是否先按原计划量房，或者我们调整个时间？",
    "因为是婚房，工期确实重要，我们可以先量房，然后尽快出方案和工期计划，这样父母看到具体安排可能会更放心。您方便的话，我也可以直接和父母沟通一下。",
    "您和父母主要看中哪些方面？我们可以针对性地准备一些资料，比如同小区案例和预算分解，方便他们参考。"
  ],
  "objectionHandling": [
    {
      "ifCustomerSays": "父母说先不量房了，等他们有空再一起看看。",
      "reply": "好的，那我们可以先加个微信，我把量房的流程和好处发给您，您转发给父母。量房不收费也不影响后期选择，随时可以约。您看方便的话，我也可以约个时间跟父母电话沟通一下。"
    },
    {
      "ifCustomerSays": "父母觉得15万预算可能不够。",
      "reply": "15万是可以做出不错效果的，我们有类似面积的案例，总价控制在15万以内。量房后我们会出详细预算清单，哪些能省哪些不能省都清清楚楚，父母看了会更放心。"
    },
    {
      "ifCustomerSays": "父母担心工期赶不上婚期。",
      "reply": "工期我们会在量房后根据实际项目给出计划，毛坯房一般2-3个月可以完成基础装修。我们会倒排工期，确保在您婚期前完工。您方便提供婚期吗？我们好提前规划。"
    }
  ],
  "recommendedMaterials": [
    "荣盛华府或同面积段已授权案例（含预算和工期）",
    "量房服务说明（强调免费、无义务）",
    "公司资质或口碑材料"
  ],
  "forbidden": [
    "不得承诺15万一定包含所有项目，不得承诺具体完工日期",
    "不得贬低父母意见或建议绕过父母决策",
    "不得以任何方式施加压力要求立即决定"
  ],
